using System;using System.Linq;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering.HighDefinition;
public static class FinishFarmDoors {
 public static string Main(){const string A="Assets/NewMap/FiveHangars";var root=GameObject.Find("New_Map").transform;var exp=root.Find("11_Five_Hangar_Farm");var steel=new Material(Shader.Find("HDRP/Lit")){name="Galvanized blue grey door steel"};steel.SetColor("_BaseColor",new Color(.34f,.42f,.47f));steel.SetFloat("_Metallic",.78f);steel.SetFloat("_Smoothness",.38f);HDMaterial.ValidateMaterial(steel);AssetDatabase.CreateAsset(steel,A+"/Galvanized door steel.mat");
 foreach(var h in exp.Cast<Transform>().Where(t=>t.name.StartsWith("Hangar 4")||t.name.StartsWith("Hangar 5")))foreach(var r in h.Cast<Transform>().First(t=>t.name.StartsWith("Locked ")).GetComponentsInChildren<MeshRenderer>())r.sharedMaterials=r.sharedMaterials.Select(m=>m.name.Contains("iron")||m.name.Contains("Shop warm")?steel:m).ToArray();
 var sign=new GameObject("Hangar 1 - open from start");sign.transform.SetParent(root.Find("01_Modular_Hangar"),false);sign.transform.localPosition=new Vector3(0,10.6f,15.45f);sign.transform.localRotation=Quaternion.Euler(0,180,0);var text=sign.AddComponent<TMPro.TextMeshPro>();text.text="HANGAR 1\nOPEN";text.fontSize=9;text.alignment=TMPro.TextAlignmentOptions.Center;text.color=new Color(.96f,.87f,.65f);text.rectTransform.sizeDelta=new Vector2(5,1.5f);text.ForceMeshUpdate();AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);return "Large hangar doors now use distinct galvanized steel; starter hall marked open.";}
}
